import { Group, PlaneGeometry, Mesh } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();

  // Resource tracking for cleanup
  const resources = {
    geometries: [],
    materials: [],
    textures: []
  };

  // Create plane geometry for button surface
  const planeGeometry = new PlaneGeometry(2.5, 0.6);
  resources.geometries.push(planeGeometry);

  // Load brushed metal texture
  const metalTexture = ctx.textureLoader.load(config.assets.imageUrl);
  metalTexture.colorSpace = 'srgb';
  resources.textures.push(metalTexture);

  // Create material
  const material = new MeshBasicNodeMaterial({
    map: metalTexture,
    toneMapped: false
  });
  resources.materials.push(material);

  // Create surface mesh
  const surfaceMesh = new Mesh(planeGeometry, material);
  group.add(surfaceMesh);

  // Render text using font atlas
  if (ctx.fontAtlas) {
    try {
      const textContent = Array.isArray(config.textContent)
        ? config.textContent[0]
        : config.textContent;

      const text = typeof textContent === 'string'
        ? textContent
        : textContent.text;

      const textMesh = ctx.fontAtlas({
        text: text || 'Get started',
        fontSize: 0.34,
        font: 'Lora',
        fontWeight: 400,
        color: '#ff2a38',
        align: 'center'
      });

      if (textMesh) {
        textMesh.position.z = 0.02;
        group.add(textMesh);
      }
    } catch (error) {
      // Font atlas unavailable, continue with surface only
    }
  }

  // Apply scene transforms
  group.position.set(0, -2.85, 0.26);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  // Setup cleanup function
  group.userData.cleanup = () => {
    resources.geometries.forEach(geometry => geometry.dispose());
    resources.materials.forEach(mat => mat.dispose());
    resources.textures.forEach(tex => tex.dispose());
  };

  group.userData.handlers = {};

  return group;
}
